import tarfile

def extract_images(tarball):
    with tarfile.open(tarball) as t:
        for name in t.getnames():
            if name.endswith('.jpg'):
                ti = t.extractfile(name)
                if ti:
                    data = ti.read()
                    with open('/var/images/' + name, 'wb') as f:
                        f.write(data)

