def find_matches(words, pattern):
    matches = []
    for word in words:
        if len(word) != len(pattern):
            continue

        pattern_map = {}
        seen_chars = set()
        match = True
        for i, char in enumerate(pattern):
            if char not in pattern_map:
                if word[i] in seen_chars:
                    match = False
                    break
                pattern_map[char] = word[i]
                seen_chars.add(word[i])
            elif pattern_map[char] != word[i]:
                match = False
                break

        if match:
            matches.append(word)

    return matches

