import os

def backup_dir(dir):
    files = []
    for f in os.listdir(dir):
        if os.path.isfile(os.path.join(dir, f)):
            files.append(f)

    tar_dir = 'backup'
    tar_files = [os.path.join(tar_dir, f) for f in files]

    os.makedirs(tar_dir, exist_ok=True)
    for src, dst in zip(files, tar_files):
        os.rename(src, dst)

